add_action( 'woocommerce_product_options_general_product_data', 'perfectpixel_external_availability_field' );
add_action( 'woocommerce_admin_process_product_object', 'perfectpixel_external_availability_save' );
add_action( 'woocommerce_external_add_to_cart', 'perfectpixel_external_availability_output', 25 );

function perfectpixel_external_availability_field() {
	echo '<div class="options_group show_if_external">';
	woocommerce_wp_select(
		array(
			'id'      => '_perfectpixel_external_stock',
			'label'   => 'Διαθεσιμότητα',
			'options' => array(
				''           => '— (να μην εμφανίζεται)',
				'instock'    => 'Διαθέσιμο',
				'outofstock' => 'Μη διαθέσιμο',
			),
		)
	);
	echo '</div>';
}

function perfectpixel_external_availability_save( $product ) {
	if ( isset( $_POST['_perfectpixel_external_stock'] ) ) {
		$value = sanitize_key( $_POST['_perfectpixel_external_stock'] );
		$product->update_meta_data( '_perfectpixel_external_stock', in_array( $value, array( 'instock', 'outofstock' ), true ) ? $value : '' );
	}
}

function perfectpixel_external_availability_output() {
	global $product;
	$status = $product ? $product->get_meta( '_perfectpixel_external_stock' ) : '';
	if ( 'instock' === $status ) {
		echo '<p class="stock in-stock">' . esc_html( '{{external_in_stock_text}}' ) . '</p>';
	} elseif ( 'outofstock' === $status ) {
		echo '<p class="stock out-of-stock">' . esc_html( '{{external_out_of_stock_text}}' ) . '</p>';
	}
}
